DateTime date = DateTime.Now;
var cal = System.Globalization.CultureInfo.InvariantCulture.Calendar;
int currentWeek = cal.GetWeekOfYear(date, System.Globalization.CalendarWeekRule.FirstFourDayWeek, DayOfWeek.Monday);
DateTime isoYearAnchor = date.AddDays(4 - (date.DayOfWeek == DayOfWeek.Sunday ? 7 : (int)date.DayOfWeek));
int currentYear = isoYearAnchor.Year;

DateTime periodStart = isoYearAnchor.AddDays(-3);
DateTime periodEnd = periodStart.AddDays(6);

Set<int>("CurrentWeekParameter", currentWeek);
Set<int>("CurrentYearParameter", currentYear);
Set<DateTime>("PeriodStartParameter", periodStart);
Set<DateTime>("PeriodEndParameter", periodEnd);
return true;
